// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// The ticketing chat's guided conversation (configuration `conversation`):
// the home screen
// settings and the button flow the visitor walks through. The whole flow is
// played here, in the widget: navigating creates nothing and calls nothing.
// Only a handoff (to the AI or the team) posts a message, and a resolved flow
// records its outcome. Pure functions: no React, no network.
import { parseShowIf, showIfHolds, type ConditionFacts, type ShowIf } from "./conditions";
import { looksLikeEmail } from "./human-mode";

export type StartMode = "text" | "buttons" | "buttons_text";
export type Opening = "cards" | "buttons" | "direct";
export type ButtonAction = "goto" | "ai" | "team" | "link" | "resolved" | "back";
export type Route = "ai" | "team";
export type CollectField = "email" | "order" | "text";
export type HandoffReason = "button" | "no" | "free_text" | "collect";
// Who takes over when the visitor asks for a person: the team, or nobody (the
// chat then shows its `none_message`).
export type Destination = "team" | "none";

export interface FlowButton {
  id: string;
  label: string;
  action: ButtonAction;
  target_step_id: string | null;
  url: string | null;
  workflow_id: string | null;
  // Offered only to visitors it holds for (see conditions.ts).
  show_if: ShowIf | null;
}

export interface FlowStep {
  id: string;
  title: string;
  text: string;
  image_url: string | null;
  kind: "message" | "collect";
  buttons: FlowButton[];
  ask_resolved: boolean;
  composer: "auto" | "hidden" | "visible";
  text_route: "default" | Route;
  collect: { field: CollectField; then: Route | "goto"; target_step_id: string | null };
}

export interface Resolution {
  question: string;
  yes: string;
  no: string;
  back: string;
  no_route: Route;
  closing: string;
}

export interface HomeCard {
  id: string;
  type: "start" | "link" | "announcement" | "recent";
  label: string;
  url: string | null;
  title: string;
  text: string;
  // Link and announcement cards only: the start and recent cards are always
  // there.
  show_if: ShowIf | null;
}

export interface HomeHeader {
  top: "avatars" | "logo" | "none";
  logo_url: string | null;
  subtitle: string;
  background: "color" | "image";
  banner_url: string | null;
}

export interface Conversation {
  start: StartMode;
  welcome: string;
  home: { opening: Opening; title: string; header: HomeHeader; cards: HomeCard[] };
  flow: { start_step_id: string | null; steps: Map<string, FlowStep>; resolution: Resolution };
  handoff: {
    default_workflow_id: string | null;
    ask_email: boolean;
    team_message: string;
    csat_after_flow: boolean;
    destination: Destination;
    none_message: string;
  };
}

// Texts used when the chat leaves one empty: the resolution buttons and the
// "nobody can take over" message are the widget's own copy in the visitor's
// language, the welcome the chat's.
export interface ConversationDefaults {
  welcome: string;
  question: string;
  yes: string;
  no: string;
  back: string;
  closing: string;
  noneMessage: string;
}

type Raw = Record<string, unknown>;

function isRecord(value: unknown): value is Raw {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function text(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function idOrNull(value: unknown): string | null {
  return typeof value === "string" && value ? value : null;
}

function oneOf<T extends string>(value: unknown, allowed: readonly T[], fallback: T): T {
  return allowed.includes(value as T) ? (value as T) : fallback;
}

// Images, logos, banners and link buttons: https only (the configuration is
// validated server-side, but a preview draft is not, and it lands in src/href).
export function httpsUrl(value: unknown): string | null {
  if (typeof value !== "string") return null;
  try {
    const url = new URL(value);
    return url.protocol === "https:" ? url.href : null;
  } catch {
    return null;
  }
}

const ACTIONS: readonly ButtonAction[] = ["goto", "ai", "team", "link", "resolved", "back"];

function parseButton(raw: unknown, index: number): FlowButton | null {
  if (!isRecord(raw) || !ACTIONS.includes(raw.action as ButtonAction)) return null;
  const label = text(raw.label).trim();
  if (!label) return null;
  return {
    id: text(raw.id) || `b${index}`,
    label,
    action: raw.action as ButtonAction,
    target_step_id: idOrNull(raw.target_step_id),
    url: httpsUrl(raw.url),
    workflow_id: idOrNull(raw.workflow_id),
    show_if: parseShowIf(raw.show_if),
  };
}

function parseStep(raw: unknown): FlowStep | null {
  if (!isRecord(raw) || !idOrNull(raw.id)) return null;
  const collect = isRecord(raw.collect) ? raw.collect : {};
  const buttons = Array.isArray(raw.buttons) ? raw.buttons : [];
  return {
    id: raw.id as string,
    title: text(raw.title),
    text: text(raw.text),
    image_url: httpsUrl(raw.image_url),
    kind: oneOf(raw.kind, ["message", "collect"], "message"),
    buttons: buttons.map(parseButton).filter((b): b is FlowButton => b !== null),
    ask_resolved: raw.ask_resolved === true,
    composer: oneOf(raw.composer, ["auto", "hidden", "visible"], "auto"),
    text_route: oneOf(raw.text_route, ["default", "ai", "team"], "default"),
    collect: {
      field: oneOf(collect.field, ["email", "order", "text"], "text"),
      then: oneOf(collect.then, ["ai", "team", "goto"], "team"),
      target_step_id: idOrNull(collect.target_step_id),
    },
  };
}

const CARD_TYPES: readonly HomeCard["type"][] = ["start", "link", "announcement", "recent"];

function parseCard(raw: unknown, index: number): HomeCard | null {
  if (!isRecord(raw) || !CARD_TYPES.includes(raw.type as HomeCard["type"])) return null;
  const type = raw.type as HomeCard["type"];
  return {
    id: text(raw.id) || `c${index}`,
    type,
    label: text(raw.label),
    url: httpsUrl(raw.url),
    title: text(raw.title),
    text: text(raw.text),
    show_if: type === "link" || type === "announcement" ? parseShowIf(raw.show_if) : null,
  };
}

// The steps as this visitor sees them: without the buttons whose condition
// does not hold for them.
function visibleSteps(steps: Map<string, FlowStep>, facts: ConditionFacts): Map<string, FlowStep> {
  const visible = new Map<string, FlowStep>();
  for (const [id, step] of steps) {
    visible.set(id, { ...step, buttons: step.buttons.filter((b) => showIfHolds(b.show_if, facts)) });
  }
  return visible;
}

function parseSteps(raw: unknown): { steps: Map<string, FlowStep>; firstId: string | null } {
  const steps = new Map<string, FlowStep>();
  for (const entry of Array.isArray(raw) ? raw : []) {
    const step = parseStep(entry);
    if (step && !steps.has(step.id)) steps.set(step.id, step);
  }
  const first = steps.keys().next();
  return { steps, firstId: first.done ? null : first.value };
}

// The chat's `conversation`, or null (no conversation: the widget stays the
// historical chat). Read defensively: an unknown value falls back to the
// simplest behavior instead of breaking the chat. With the visitor's `facts`,
// the cards and buttons whose condition does not hold for them are left out;
// without (the editor's preview), everything is shown.
export function parseConversation(
  raw: unknown,
  defaults: ConversationDefaults,
  facts: ConditionFacts | null = null
): Conversation | null {
  if (!isRecord(raw)) return null;
  const flowRaw = isRecord(raw.flow) ? raw.flow : {};
  const homeRaw = isRecord(raw.home) ? raw.home : {};
  const headerRaw = isRecord(homeRaw.header) ? homeRaw.header : {};
  const resolutionRaw = isRecord(flowRaw.resolution) ? flowRaw.resolution : {};
  const handoffRaw = isRecord(raw.handoff) ? raw.handoff : {};

  const parsed = parseSteps(flowRaw.steps);
  const steps = facts ? visibleSteps(parsed.steps, facts) : parsed.steps;
  const firstId = parsed.firstId;
  const requestedStart = idOrNull(flowRaw.start_step_id);
  const startStepId = requestedStart && steps.has(requestedStart) ? requestedStart : firstId;
  // Without a step to start from, visitors can only write.
  const start: StartMode = startStepId ? oneOf(raw.start, ["text", "buttons", "buttons_text"], "text") : "text";

  const cards = (Array.isArray(homeRaw.cards) ? homeRaw.cards : [])
    .map(parseCard)
    .filter((c): c is HomeCard => c !== null && (!facts || showIfHolds(c.show_if, facts)));
  let opening = oneOf(homeRaw.opening, ["cards", "buttons", "direct"], "direct");
  // The start buttons only exist when visitors click.
  const startButtons = startStepId ? steps.get(startStepId)?.buttons ?? [] : [];
  if (opening === "buttons" && (start === "text" || startButtons.length === 0)) opening = "cards";
  // A home screen always offers a way into the conversation.
  if (opening === "cards" && !cards.some((c) => c.type === "start")) {
    cards.push({ id: "start", type: "start", label: "", url: null, title: "", text: "", show_if: null });
  }

  return {
    start,
    welcome: text(raw.welcome).trim() ? text(raw.welcome) : defaults.welcome,
    home: {
      opening,
      title: text(homeRaw.title),
      header: {
        top: oneOf(headerRaw.top, ["avatars", "logo", "none"], "avatars"),
        logo_url: httpsUrl(headerRaw.logo_url),
        subtitle: text(headerRaw.subtitle),
        background: oneOf(headerRaw.background, ["color", "image"], "color"),
        banner_url: httpsUrl(headerRaw.banner_url),
      },
      cards,
    },
    flow: {
      start_step_id: startStepId,
      steps,
      resolution: {
        question: text(resolutionRaw.question).trim() || defaults.question,
        yes: text(resolutionRaw.yes).trim() || defaults.yes,
        no: text(resolutionRaw.no).trim() || defaults.no,
        back: text(resolutionRaw.back).trim() || defaults.back,
        no_route: oneOf(resolutionRaw.no_route, ["team", "ai"], "team"),
        closing: text(resolutionRaw.closing).trim() || defaults.closing,
      },
    },
    handoff: {
      default_workflow_id: idOrNull(handoffRaw.default_workflow_id),
      ask_email: handoffRaw.ask_email === true,
      team_message: text(handoffRaw.team_message),
      csat_after_flow: handoffRaw.csat_after_flow === true,
      destination: oneOf(handoffRaw.destination, ["team", "none"], "team"),
      none_message: text(handoffRaw.none_message).trim() ? text(handoffRaw.none_message) : defaults.noneMessage,
    },
  };
}

// The guided conversation of a widget configuration: only the ticketing
// chat's (mode "human") and only when set. The Shop Assistant, and every chat
// whose `conversation` is null, keep the historical widget.
export function conversationOf(
  config: { mode?: unknown; conversation?: unknown },
  defaults: ConversationDefaults,
  facts: ConditionFacts | null = null
): Conversation | null {
  return config.mode === "human" ? parseConversation(config.conversation, defaults, facts) : null;
}

// What restarts the conversation when the chat's settings change (the
// editor's live preview): how visitors start, the home screen, the first step.
export function conversationKey(conversation: Conversation | null): string {
  if (!conversation) return "none";
  return [conversation.start, conversation.home.opening, conversation.flow.start_step_id ?? ""].join("|");
}

// ---------------------------------------------------------------------------
// The visitor's walk through the flow

export interface PathEntry {
  step_id: string;
  step_title: string;
  // The clicked button; empty where the visitor wrote instead (the server
  // then shows the step's title).
  choice_label: string;
}

export interface Collected {
  email?: string;
  order?: string;
  text?: string;
}

// `flow`, posted with the message that opens the ticket.
export interface FlowPayload {
  path: PathEntry[];
  route: Route;
  workflow_id: string | null;
  reason: HandoffReason;
  collected: Collected;
}

type Pending =
  | { kind: "collect"; stepId: string }
  // A handoff to the team waiting for the visitor's email.
  | { kind: "email"; body: string; flow: FlowPayload };

export interface FlowState {
  // The step on screen: its buttons are live, what the visitor writes is read
  // against it. null once handed off or resolved.
  stepId: string | null;
  // Steps to go back to.
  stack: string[];
  path: PathEntry[];
  pending: Pending | null;
  collected: Collected;
  // open: the visitor is in the flow; handed_off: a ticket carries the
  // conversation (what they write is a plain message); resolved: the flow
  // answered (writing again opens a ticket).
  status: "open" | "handed_off" | "resolved";
}

export type FlowOutput =
  | { from: "bot"; text: string; image_url: string | null; question: string | null }
  | { from: "visitor"; text: string }
  | { from: "system"; text: string }
  | { from: "csat" };

export type FlowEffect =
  | { kind: "handoff"; body: string; flow: FlowPayload }
  | { kind: "resolved"; path: PathEntry[] }
  // Nobody can take over: the chat's message was shown, nothing is sent.
  | { kind: "unavailable" };

export interface Transition {
  state: FlowState;
  // The visitor's bubble, shown at once; the bot's replies follow.
  visitor: string | null;
  bot: FlowOutput[];
  effect: FlowEffect | null;
  error?: "invalid_email";
}

export interface FlowContext {
  // The chat lets Achille's AI answer (ai_enabled). Off, every handoff goes
  // to the team.
  aiEnabled: boolean;
  // An email is on file (shopper identity, pre-chat or collected).
  emailKnown: boolean;
  // Outside business hours the team can only answer by email.
  offline: boolean;
  // The bot's question before a handoff to the team without an email.
  askEmailText: string;
}

export function initialFlowState(status: FlowState["status"] = "open"): FlowState {
  return { stepId: null, stack: [], path: [], pending: null, collected: {}, status };
}

function stepMessage(conversation: Conversation, step: FlowStep): FlowOutput {
  const question = step.kind === "message" && step.ask_resolved ? conversation.flow.resolution.question : null;
  return { from: "bot", text: step.text, image_url: step.image_url, question };
}

function show(conversation: Conversation, state: FlowState, step: FlowStep, visitor: string | null): Transition {
  return {
    state: {
      ...state,
      stepId: step.id,
      pending: step.kind === "collect" ? { kind: "collect", stepId: step.id } : null,
      status: "open",
    },
    visitor,
    bot: [stepMessage(conversation, step)],
    effect: null,
  };
}

// A new conversation: the first step, or the welcome message when visitors
// write.
export function startFlow(conversation: Conversation): { state: FlowState; bot: FlowOutput[] } {
  const step = startStep(conversation);
  if (conversation.start === "text" || !step) {
    return { state: initialFlowState(), bot: [{ from: "bot", text: conversation.welcome, image_url: null, question: null }] };
  }
  const { state, bot } = show(conversation, initialFlowState(), step, null);
  return { state, bot };
}

// The first step without showing it: a start button clicked on the home
// screen acts from there.
export function enterAtStart(conversation: Conversation, state: FlowState): FlowState {
  const step = startStep(conversation);
  if (!step) return state;
  return { ...state, stepId: step.id, pending: null, status: "open" };
}

function startStep(conversation: Conversation): FlowStep | null {
  const id = conversation.flow.start_step_id;
  return (id && conversation.flow.steps.get(id)) || null;
}

function currentStep(conversation: Conversation, state: FlowState): FlowStep | null {
  return (state.stepId && conversation.flow.steps.get(state.stepId)) || null;
}

export interface Choice {
  key: string;
  label: string;
  action: ButtonAction | "no";
  target_step_id: string | null;
  url: string | null;
  workflow_id: string | null;
}

function choiceOf(key: string, label: string, action: Choice["action"]): Choice {
  return { key, label, action, target_step_id: null, url: null, workflow_id: null };
}

// Whether a person can take over in this chat. With handoff.destination
// "none", the widget offers no way to reach the team.
export function teamCanTakeOver(conversation: Conversation): boolean {
  return conversation.handoff.destination !== "none";
}

// A step's buttons. With the end question: "no" and "yes" first, then the
// step's own buttons, then a way back when there is somewhere to go back to.
// "no" is left out when it leads to a team the chat does not have.
export function choicesFor(conversation: Conversation, step: FlowStep, canGoBack: boolean): Choice[] {
  const own: Choice[] = step.buttons.map((b) => ({ key: b.id, ...b }));
  if (step.kind !== "message" || !step.ask_resolved) return own;
  const r = conversation.flow.resolution;
  const hasBack = own.some((b) => b.action === "back");
  const offerNo = r.no_route === "ai" || teamCanTakeOver(conversation);
  return [
    ...(offerNo ? [choiceOf("__no", r.no, "no")] : []),
    choiceOf("__yes", r.yes, "resolved"),
    ...own,
    ...(hasBack || !canGoBack ? [] : [choiceOf("__back", r.back, "back")]),
  ];
}

// The buttons on screen now (none while the visitor answers a question).
export function liveChoices(conversation: Conversation, state: FlowState): Choice[] {
  const step = currentStep(conversation, state);
  if (!step || state.pending) return [];
  return choicesFor(conversation, step, state.stack.length > 0);
}

// Short choices (shop names, sizes) as chips side by side, a list otherwise.
// The way back does not count.
export function choiceLayout(choices: readonly Choice[]): "chips" | "list" {
  const counted = choices.filter((c) => c.action !== "back");
  return counted.length >= 3 && counted.every((c) => Array.from(c.label).length <= 16) ? "chips" : "list";
}

// Whether the composer is on screen. A question waiting for an answer, a
// chat where visitors write, a ticket in progress or a finished flow: yes.
// Otherwise the step decides, "auto" following how visitors start.
export function composerVisible(conversation: Conversation, state: FlowState, hasTicket: boolean): boolean {
  if (state.pending || conversation.start === "text" || hasTicket || state.status !== "open") return true;
  const step = currentStep(conversation, state);
  if (!step) return conversation.start === "buttons_text";
  if (step.composer === "visible") return true;
  if (step.composer === "hidden") return false;
  return conversation.start === "buttons_text";
}

// The field a pending question asks for, for the composer's placeholder.
export function pendingField(conversation: Conversation, state: FlowState): CollectField | null {
  const pending = state.pending;
  if (!pending) return null;
  if (pending.kind === "email") return "email";
  return conversation.flow.steps.get(pending.stepId)?.collect.field ?? null;
}

function entry(step: FlowStep, choiceLabel: string): PathEntry {
  return { step_id: step.id, step_title: step.title, choice_label: choiceLabel };
}

function handoff(
  conversation: Conversation,
  state: FlowState,
  requested: Route,
  workflowId: string | null,
  reason: HandoffReason,
  body: string,
  ctx: FlowContext
): Transition {
  const route: Route = ctx.aiEnabled ? requested : "team";
  if (route === "team" && conversation.handoff.destination === "none") return unavailable(conversation, body);
  const flow: FlowPayload = {
    path: state.path,
    route,
    workflow_id: route === "ai" ? workflowId : null,
    reason,
    collected: state.collected,
  };
  const needsEmail =
    route === "team" &&
    (conversation.handoff.ask_email || ctx.offline) &&
    !ctx.emailKnown &&
    !state.collected.email;
  if (needsEmail) {
    return {
      state: { ...state, stepId: null, pending: { kind: "email", body, flow } },
      visitor: body,
      bot: [{ from: "bot", text: ctx.askEmailText, image_url: null, question: null }],
      effect: null,
    };
  }
  return {
    state: { ...state, stepId: null, pending: null, status: "handed_off" },
    visitor: body,
    bot: [],
    effect: { kind: "handoff", body, flow },
  };
}

// Nobody can take over (handoff.destination "none"): the chat's message in
// place of a handoff to the team, with no ticket and no email asked. The flow
// is over: what the visitor writes next starts afresh.
function unavailable(conversation: Conversation, body: string): Transition {
  return {
    state: initialFlowState("resolved"),
    visitor: body,
    bot: [{ from: "bot", text: conversation.handoff.none_message, image_url: null, question: null }],
    effect: { kind: "unavailable" },
  };
}

function resolve(conversation: Conversation, state: FlowState, label: string): Transition {
  const bot: FlowOutput[] = [
    { from: "bot", text: conversation.flow.resolution.closing, image_url: null, question: null },
  ];
  if (conversation.handoff.csat_after_flow) bot.push({ from: "csat" });
  return {
    state: initialFlowState("resolved"),
    visitor: label,
    bot,
    effect: { kind: "resolved", path: state.path },
  };
}

// A button clicked on the current step. null when nothing happens (a link
// opens by itself; a dangling target is ignored).
export function choose(conversation: Conversation, state: FlowState, choice: Choice, ctx: FlowContext): Transition | null {
  const step = currentStep(conversation, state);
  if (!step || choice.action === "link") return null;
  const base: FlowState = { ...state, path: [...state.path, entry(step, choice.label)] };
  switch (choice.action) {
    case "goto": {
      const target = choice.target_step_id ? conversation.flow.steps.get(choice.target_step_id) : null;
      if (!target) return null;
      return show(conversation, { ...base, stack: [...state.stack, step.id] }, target, choice.label);
    }
    case "back": {
      const previousId = state.stack.length ? state.stack[state.stack.length - 1] : conversation.flow.start_step_id;
      const previous = previousId ? conversation.flow.steps.get(previousId) : null;
      if (!previous) return null;
      return show(conversation, { ...base, stack: state.stack.slice(0, -1) }, previous, choice.label);
    }
    case "resolved":
      return resolve(conversation, base, choice.label);
    case "no":
      return handoff(conversation, base, conversation.flow.resolution.no_route, conversation.handoff.default_workflow_id, "no", choice.label, ctx);
    case "team":
      return handoff(conversation, base, "team", null, "button", choice.label, ctx);
    case "ai":
      return handoff(conversation, base, "ai", choice.workflow_id, "button", choice.label, ctx);
  }
}

// After the AI answered, the visitor asks for a person. The server follows
// the flow of the last message that carries one, so this message tells the
// orchestrator to stop answering.
export function escalateToTeam(conversation: Conversation, state: FlowState, label: string, ctx: FlowContext): Transition {
  return handoff(conversation, { ...state, stepId: null, pending: null }, "team", null, "button", label, ctx);
}

// What the visitor wrote. null when the flow has nothing to do with it (a
// ticket carries the conversation: it is a plain message).
export function submitText(conversation: Conversation, state: FlowState, raw: string, ctx: FlowContext): Transition | null {
  const value = raw.trim();
  if (!value) return null;
  const pending = state.pending;

  if (pending?.kind === "email") {
    if (!looksLikeEmail(value)) return { state, visitor: null, bot: [], effect: null, error: "invalid_email" };
    const collected = { ...state.collected, email: value };
    return {
      state: { ...state, pending: null, collected, status: "handed_off" },
      visitor: value,
      bot: [],
      effect: { kind: "handoff", body: pending.body, flow: { ...pending.flow, collected } },
    };
  }

  if (pending?.kind === "collect") {
    const step = conversation.flow.steps.get(pending.stepId);
    if (step) return answerCollect(conversation, state, step, value, ctx);
  }

  if (state.status === "handed_off") return null;
  // Free text while browsing, or after a resolved flow: it opens a ticket.
  const step = currentStep(conversation, state);
  const route: Route = step && step.text_route !== "default" ? step.text_route : "ai";
  const path = step ? [...state.path, entry(step, "")] : state.path;
  return handoff(conversation, { ...state, path }, route, conversation.handoff.default_workflow_id, "free_text", value, ctx);
}

// A question asked from the storefront (the product page box) while the flow
// is on screen: free text from wherever the visitor is, the step's buttons and
// any pending question set aside. null once a ticket carries the conversation
// (it is a plain message).
export function askFromStorefront(conversation: Conversation, state: FlowState, raw: string, ctx: FlowContext): Transition | null {
  if (state.status === "handed_off") return null;
  return submitText(conversation, { ...state, stepId: null, pending: null }, raw, ctx);
}

function answerCollect(conversation: Conversation, state: FlowState, step: FlowStep, value: string, ctx: FlowContext): Transition {
  const { field, then, target_step_id } = step.collect;
  if (field === "email" && !looksLikeEmail(value)) {
    return { state, visitor: null, bot: [], effect: null, error: "invalid_email" };
  }
  const base: FlowState = {
    ...state,
    pending: null,
    collected: { ...state.collected, [field]: value },
    path: [...state.path, entry(step, "")],
  };
  if (then === "goto") {
    const target = target_step_id ? conversation.flow.steps.get(target_step_id) : null;
    if (target) return show(conversation, { ...base, stack: [...state.stack, step.id] }, target, value);
    return { state: base, visitor: value, bot: [], effect: null };
  }
  return handoff(conversation, base, then, conversation.handoff.default_workflow_id, "collect", value, ctx);
}

// ---------------------------------------------------------------------------
// The thread: the server's messages (a ticket's) and the flow's own lines

// A line of the flow remembers the server message it came after (null:
// before them all), so a flow started below a ticket's history, or a request
// for the team after the AI's reply, lands where it happened.
export type ThreadEntry<T, F> =
  | { kind: "server"; message: T; index: number }
  | { kind: "flow"; item: F; index: number };

// Never a message id.
const AT_END = "\u0000end";

// The server's messages and the flow's lines in order. The server copy of a
// message the flow already shows as the visitor's bubble is hidden. A line
// whose message is gone (an optimistic copy replaced by the server's) goes
// last. `index`: in `visible` for a message, in `items` for a line.
export function interleave<T extends { id: string }, F extends { after: string | null }>(
  messages: readonly T[],
  items: readonly F[],
  hiddenIds: readonly string[]
): { visible: T[]; entries: ThreadEntry<T, F>[] } {
  const known = new Set(messages.map((m) => m.id));
  const anchored = new Map<string | null, ThreadEntry<T, F>[]>();
  items.forEach((item, index) => {
    const anchor = item.after === null || known.has(item.after) ? item.after : AT_END;
    anchored.set(anchor, [...(anchored.get(anchor) ?? []), { kind: "flow", item, index }]);
  });
  const visible = messages.filter((m) => !hiddenIds.includes(m.id));
  const entries: ThreadEntry<T, F>[] = [...(anchored.get(null) ?? [])];
  for (const message of messages) {
    const index = visible.indexOf(message);
    if (index >= 0) entries.push({ kind: "server", message, index });
    entries.push(...(anchored.get(message.id) ?? []));
  }
  entries.push(...(anchored.get(AT_END) ?? []));
  return { visible, entries };
}
